const MOB = "cb_t11_mob"
const GUN = item(iron_horse_armor, name: "&7Пистолет", tags: {weapon: "cb_t11"})
const RANGE = 30

func cb_t11_shoot(power: number) {
    player_by_conditional(not player.name_equals(value.uuid))
    stop = filter_by_raycast(value.eye_location, RANGE, 0.15, 1, consider_blocks: true)
    @current player.damage(power, value.uuid)
    if value.selection_size == 0 {
        all_mobs()
        stop = filter_by_raycast(value.eye_location, RANGE, 0.15, 1, consider_blocks: true)
        @current entity.damage(power, value.uuid)
    }
    @all display_particle_line(particle(crit), value.eye_location, stop, 0.5, unit_of_measurement: distance)
    hp = @current value.current_health
    @default send_message("t11 попал %selected% hp=${hp}")
    reset()
}

