func cb_t12_march(limit: number) {
    pos = value.eye_location
    dir = value.direction_of_view
    repeat limit * 2 {
        pos = shift_location_on_vector(pos, dir, 0.5)
        if not game.block_equals(block(air), pos) {
            return "блок"
        }
    }
    return "мимо"
}

when player_chat {
    if not chat_message_equals("@t12") {
        end_thread()
    }
    cancel_event()
    hit = ray_trace_result(start: value.eye_location, max_distance: 20, ray_size: 0, ray_collision_mode: only_blocks)
    ray = "мимо"
    if var.is_type(hit, location) {
        ray = "блок"
    }
    send_message("t12 луч=${ray} шаги=${cb_t12_march(20)}")
}

